const re = /(?<year>\d{4})-(?<month>\d{2})-(?<day>\d{2})/;
const match = 'Released 2024-03-09'.match(re);

console.log(match.groups.year);  // '2024'
console.log(match.groups);       // [Object: null prototype] { year: '2024', month: '03', day: '09' }
console.log(match[1]);           // '2024'

/\k<word>(?<word>\w+)/.exec('abc');
// ['abc', 'abc']  forward reference matched '' and the group then matched 'abc'

/(?<a>x)?\k<a>y/.exec('y');
// ['y', undefined]  group a did not participate, so \k<a> matched ''

const log = 'a=1 b=22 c=333';

for (const m of log.matchAll(/(?<key>\w+)=(?<value>\d+)/g)) {
  const { key, value } = m.groups;
  console.log(key, value);
}
// a 1
// b 22
// c 333

